-- Captures are private inputs, not content revisions or deployed versions.
CREATE TABLE publish_captures (sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, purpose TEXT NOT NULL CHECK(purpose IN ('preview','publish')), revision INTEGER NOT NULL CHECK(revision >= 0), status TEXT NOT NULL DEFAULT 'capturing' CHECK(status IN ('capturing','ready','failed','expired')), input_sha256 TEXT NOT NULL CHECK(length(input_sha256) = 64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'), snapshot_sha256 TEXT NOT NULL CHECK(length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 2097152), created_at TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at > created_at), updated_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, failure_code TEXT CHECK(failure_code IN ('interrupted','integrity')), CHECK((status = 'failed' AND failure_code IS NOT NULL) OR (status != 'failed' AND failure_code IS NULL)));
CREATE INDEX publish_captures_expiry ON publish_captures(status, expires_at);
CREATE TRIGGER publish_capture_revision BEFORE INSERT ON publish_captures WHEN NEW.revision IS NOT (SELECT revision FROM platform_state WHERE id = 1) BEGIN SELECT RAISE(ABORT, 'Publish revision conflict'); END;
CREATE TRIGGER publish_capture_storage_cap BEFORE INSERT ON publish_captures WHEN (SELECT COUNT(*) FROM publish_captures WHERE status != 'expired') >= 20 BEGIN SELECT RAISE(ABORT, 'Publish capture storage budget reached'); END;
CREATE TRIGGER publish_capture_initial_status BEFORE INSERT ON publish_captures WHEN NEW.status != 'capturing' BEGIN SELECT RAISE(ABORT, 'Invalid initial capture status'); END;
CREATE TRIGGER publish_capture_immutable BEFORE UPDATE ON publish_captures WHEN NEW.sequence IS NOT OLD.sequence OR NEW.id IS NOT OLD.id OR NEW.purpose IS NOT OLD.purpose OR NEW.revision IS NOT OLD.revision OR NEW.input_sha256 IS NOT OLD.input_sha256 OR NEW.snapshot_sha256 IS NOT OLD.snapshot_sha256 OR NEW.byte_size IS NOT OLD.byte_size OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_by IS NOT OLD.created_by BEGIN SELECT RAISE(ABORT, 'Publish capture identity is immutable'); END;
CREATE TRIGGER publish_capture_transition BEFORE UPDATE OF status ON publish_captures WHEN NEW.status != OLD.status AND NOT ((OLD.status = 'capturing' AND NEW.status IN ('ready','failed','expired')) OR (OLD.status IN ('ready','failed') AND NEW.status = 'expired')) BEGIN SELECT RAISE(ABORT, 'Invalid capture transition'); END;
CREATE TRIGGER publish_capture_audit_insert AFTER INSERT ON publish_captures BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.created_by,'publish.capture.requested','capture:' || NEW.id,NEW.created_at); END;
CREATE TRIGGER publish_capture_audit_status AFTER UPDATE OF status ON publish_captures WHEN NEW.status != OLD.status BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.updated_by,'publish.capture.' || NEW.status,'capture:' || NEW.id,NEW.updated_at); END;
CREATE TRIGGER publish_capture_no_delete BEFORE DELETE ON publish_captures BEGIN SELECT RAISE(ABORT, 'Publish capture history is retained'); END;
